"""DEMO-ONLY supervisor for the Tarkado full-loop stack (one Replit workflow).

Processes (all bound to loopback or the private socket, except the bridge):
  * company service  `engine company service` on <store>/company.sock, with the
                      reviewed DEMO integration manifest (operator-approved load)
  * LiteLLM proxy     127.0.0.1:4000, config regenerated by the runner
  * bridge            :8000 -> company socket, :3000 -> LiteLLM (see bridge.py)

  * OpenCode servers  one `opencode serve` per developer persona on loopback
                      (4101 senior, 4102 junior), each with its own HOME/XDG

The runner controls LiteLLM with signals to this supervisor:
  SIGHUP   (re)start LiteLLM from the current private config
  SIGUSR1  kill LiteLLM immediately (failure drill) and keep it stopped
and each OpenCode server with flag files in run/: opencode-<name>.enabled keeps
it running; touching opencode-<name>.restart restarts it (new config/plugin).
State lives under local/full-loop/ (gitignored). Nothing here prints secrets.
"""

import json
import os
import signal
import subprocess
import sys
import time
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
DEMO = Path(__file__).resolve().parent
STATE = ROOT / "local" / "full-loop"
PRIVATE = STATE / "private"
RUN = STATE / "run"
PYTHON = str(ROOT / ".venv" / "bin" / "python")
OPENCODE = str(ROOT / "local" / "opencode-host" / "node_modules" / "@opencode" / "cli" / "bin" / "opencode.exe")
OPENCODE_PORTS = {"senior": 4101, "junior": 4102}
CHILD_ENV = {key: value for key, value in os.environ.items() if not key.startswith("AI_INTEGRATIONS_")}


def log(message):
    print(time.strftime("%H:%M:%S"), message, flush=True)


class Stack:
    def __init__(self):
        self.company = self.litellm = self.bridge = None
        self.opencode = {}
        self.want_litellm = (RUN / "litellm.enabled").exists()
        self.restart_litellm = False

    def company_ready(self):
        return all((PRIVATE / name).exists() for name in ("deployment.json", "integration-manifest.json", "integration-config.json")) \
            and (STATE / "store" / "company.sqlite3").exists()

    def start_company(self):
        socket = STATE / "store" / "company.sock"
        if socket.exists() or socket.is_symlink():
            socket.unlink()  # only this supervisor serves this demo store
        env = dict(CHILD_ENV, PYTHONPATH=f"{ROOT}:{DEMO}", TARKADO_DEMO_INTEGRATION_CONFIG=str(PRIVATE / "integration-config.json"))
        self.company = subprocess.Popen([PYTHON, "-m", "engine", "company", "service", "--store", str(STATE / "store"),
                                         "--deployment", str(PRIVATE / "deployment.json"),
                                         "--integration-manifest", str(PRIVATE / "integration-manifest.json"),
                                         "--load-reviewed-integration"], cwd=ROOT, env=env)
        log(f"company service started (pid {self.company.pid})")

    def start_litellm(self):
        config = PRIVATE / "litellm.yaml"
        if not config.exists():
            log("LiteLLM config not written yet; not starting")
            return
        # No database: LiteLLM would otherwise pick up the workspace DATABASE_URL and
        # try to use Prisma. The demo gateway needs no LiteLLM key/spend tables.
        base = {key: value for key, value in os.environ.items() if key != "DATABASE_URL" and not key.startswith("PG")}
        env = dict(base, PYTHONPATH=f"{ROOT}:{DEMO}", DEMO_GATEWAY_KEYS=str(PRIVATE / "gateway-keys.json"),
                   LITELLM_LOG="ERROR", LITELLM_TELEMETRY="False", DISABLE_SCHEMA_UPDATE="True",
                   LITELLM_MASTER_KEY=(PRIVATE / "litellm-master.key").read_text().strip())
        gateway = PRIVATE / "gateway-config.json"
        if gateway.exists():
            env["TARKADO_GATEWAY_CONFIG"] = str(gateway)
        logfile = open(RUN / "litellm.log", "ab")
        self.litellm = subprocess.Popen([PYTHON, "-m", "litellm.proxy.proxy_cli", "--config", str(config), "--host", "127.0.0.1",
                                         "--port", "4000", "--num_workers", "1"], cwd=ROOT, env=env, stdout=logfile, stderr=subprocess.STDOUT)
        log(f"LiteLLM started (pid {self.litellm.pid}); output in local/full-loop/run/litellm.log")

    def start_opencode(self, name):
        person = json.loads((PRIVATE / "personas.json").read_text())[name]
        base = STATE / "work" / name / "oc"
        env = {"PATH": os.environ["PATH"], "HOME": str(base / "home"), "XDG_CONFIG_HOME": str(base / "xdg" / "config"),
               "XDG_DATA_HOME": str(base / "xdg" / "data"), "XDG_CACHE_HOME": str(base / "xdg" / "cache"),
               "XDG_STATE_HOME": str(base / "xdg" / "state"), "LANG": "C.UTF-8", "OPENCODE_DISABLE_AUTOUPDATE": "1",
               "COMPANY_GATEWAY_KEY": person["gateway_key"], "OPENCODE_SERVER_PASSWORD": person["opencode_password"]}
        for key in ("HOME", "XDG_CONFIG_HOME", "XDG_DATA_HOME", "XDG_CACHE_HOME", "XDG_STATE_HOME"):
            Path(env[key]).mkdir(parents=True, exist_ok=True)
        logfile = open(RUN / f"opencode-{name}.log", "ab")
        self.opencode[name] = subprocess.Popen([OPENCODE, "serve", "--hostname", "127.0.0.1", "--port", str(OPENCODE_PORTS[name])],
                                               cwd=STATE / "work" / name / "repo", env=env, stdout=logfile, stderr=subprocess.STDOUT)
        log(f"OpenCode server for {name} started (pid {self.opencode[name].pid})")

    def supervise_opencode(self):
        for name in OPENCODE_PORTS:
            process = self.opencode.get(name)
            if (RUN / f"opencode-{name}.restart").exists():
                (RUN / f"opencode-{name}.restart").unlink()
                self.stop(process, f"OpenCode server for {name}")
                process = self.opencode[name] = None
            if not (RUN / f"opencode-{name}.enabled").exists():
                if process is not None:
                    self.stop(process, f"OpenCode server for {name}")
                    self.opencode[name] = None
                continue
            if process is None or process.poll() is not None:
                if process is not None:
                    log(f"OpenCode server for {name} exited with {process.returncode}; restarting in 3s")
                    time.sleep(3)
                self.start_opencode(name)

    def stop(self, process, name, sig=signal.SIGTERM):
        if process is not None and process.poll() is None:
            process.send_signal(sig)
            try:
                process.wait(10)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()
            log(f"{name} stopped")

    def on_hup(self, *_):
        self.want_litellm = True
        self.restart_litellm = True
        (RUN / "litellm.enabled").touch()

    def on_usr1(self, *_):
        self.want_litellm = False
        (RUN / "litellm.enabled").unlink(missing_ok=True)
        if self.litellm is not None and self.litellm.poll() is None:
            self.litellm.kill()  # failure drill: abrupt loss mid-attempt
            self.litellm.wait()
            log("LiteLLM killed (failure drill)")
        self.litellm = None

    def run(self):
        RUN.mkdir(parents=True, exist_ok=True)
        (RUN / "stack.pid").write_text(str(os.getpid()))
        signal.signal(signal.SIGHUP, self.on_hup)
        signal.signal(signal.SIGUSR1, self.on_usr1)
        signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))
        host = os.environ["REPLIT_DEV_DOMAIN"]
        self.bridge = subprocess.Popen([PYTHON, str(DEMO / "bridge.py"), host, str(STATE / "store" / "company.sock")], cwd=ROOT, env=CHILD_ENV)
        try:
            while True:
                if self.bridge.poll() is not None:
                    log("bridge exited; restarting")
                    self.bridge = subprocess.Popen([PYTHON, str(DEMO / "bridge.py"), host, str(STATE / "store" / "company.sock")], cwd=ROOT, env=CHILD_ENV)
                if (RUN / "company.restart").exists():
                    (RUN / "company.restart").unlink()
                    self.stop(self.company, "company service")
                    self.company = None
                if self.company is None or self.company.poll() is not None:
                    if self.company is not None:
                        log(f"company service exited with {self.company.returncode}; restarting in 3s")
                        time.sleep(3)
                    self.company = None
                    if self.company_ready():
                        self.start_company()
                if self.restart_litellm:
                    self.restart_litellm = False
                    self.stop(self.litellm, "LiteLLM")
                    self.litellm = None
                if self.want_litellm and (self.litellm is None or self.litellm.poll() is not None):
                    if self.litellm is not None:
                        log(f"LiteLLM exited with {self.litellm.returncode}; restarting in 3s")
                        time.sleep(3)
                    self.start_litellm()
                self.supervise_opencode()
                time.sleep(1)
        finally:
            for name, process in self.opencode.items():
                self.stop(process, f"OpenCode server for {name}")
            for process, name in ((self.litellm, "LiteLLM"), (self.company, "company service"), (self.bridge, "bridge")):
                self.stop(process, name)


if __name__ == "__main__":
    Stack().run()
